import re,os
def mod2path(m): return m.replace('.','/')+'.lean'
def imports(p):
    if not os.path.exists(p): return []
    out=[]
    for l in open(p, errors='ignore'):
        l=l.strip()
        if l.startswith('import '): out.append(l.split()[1])
        elif l and not l.startswith('--') and not l.startswith('/-'): break
    return out
seen=set(); stack=[m for m in imports('AlgebraicJacobian.lean') if m.startswith('AlgebraicJacobian')]
print('direct root imports (AlgebraicJacobian.*):', len(stack))
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(mod2path(m)):
        if i.startswith('AlgebraicJacobian') and i not in seen: stack.append(i)
ondisk=set()
for r,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): ondisk.add(os.path.join(r,f)[:-5].replace('/','.'))
print('on disk:', len(ondisk))
print('reachable:', len(seen & ondisk))
print('unrooted:', len(ondisk - seen))
EOF

